/// Static facts about a block type (`ChunkerVanillaBlockType` constructor arguments).
#[derive(Clone, Copy, Debug)]
pub struct BlockInfo {
    /// Map colour (0xRRGGBB).
    pub rgb: u32,
    /// Every face is solid (a full cube).
    pub solid: bool,
    /// Index into `STATE_SETS`.
    pub set: u16,
    /// `BlockGroup` bit set.
    pub groups: u16,
    /// The block entity the block uses, if any.
    pub entity: Option<K>,
}

const fn b(rgb: u32, solid: bool, set: u16, groups: u16, entity: Option<K>) -> BlockInfo {
    BlockInfo { rgb, solid, set, groups, entity }
}

